import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { configSchema, type ConfigInput } from '../src/lib/schema';

/**
 * Parses markdown generated by GitHub Issue Forms into a key-value record.
 */
export function parseIssueBody(markdown: string): Record<string, string> {
  const sections: Record<string, string> = {};
  const lines = markdown.split('\n');

  let currentHeading: string | null = null;
  let currentContent: string[] = [];

  for (const line of lines) {
    const headingMatch = line.match(/^###\s+(.+)$/);
    if (headingMatch) {
      if (currentHeading) {
        sections[currentHeading] = currentContent.join('\n').trim();
      }
      currentHeading = headingMatch[1].trim();
      currentContent = [];
    } else if (currentHeading) {
      currentContent.push(line);
    }
  }

  if (currentHeading) {
    sections[currentHeading] = currentContent.join('\n').trim();
  }

  return sections;
}

export async function convertIssueToConfig(
  issueAuthor: string,
  issueBody: string,
): Promise<{ config: ConfigInput; author: string; slug: string }> {
  const fields = parseIssueBody(issueBody);

  const name = fields['Nom de la configuration'] || fields['Configuration Name'] || '';
  const slug = (fields['Identifiant court (slug)'] || fields['Slug'] || '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9-]/g, '-');
  const summary = fields['Résumé court (1 phrase)'] || fields['Short Summary'] || '';
  const description = fields['Description détaillée (facultatif)'] || fields['Description'] || undefined;
  const license = fields['Licence (identifiant SPDX)'] || fields['License (SPDX)'] || 'MIT';
  const wm = (fields['Gestionnaire de fenêtres / Compositeur'] || fields['Window Manager'] || '').toLowerCase();
  const displayServerRaw = (fields['Serveur d\'affichage'] || fields['Display Server'] || 'wayland').toLowerCase();
  const displayServer = displayServerRaw.includes('x11') ? (displayServerRaw.includes('wayland') ? 'both' : 'x11') : 'wayland';

  const distrosRaw = fields['Distributions supportées'] || fields['Distributions'] || 'arch';
  const distros = distrosRaw
    .split(/[\n,]/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean) as any[];

  const tagsRaw = fields['Tags / Mots-clés'] || fields['Tags'] || '';
  const tags = tagsRaw
    .split(/[\n, ]/)
    .map((s) => s.trim().toLowerCase().replace(/^#/, ''))
    .filter(Boolean);

  const screenshotsRaw = fields['URLs des captures d\'écran'] || fields['Screenshots URLs'] || '';
  const screenshotUrls = screenshotsRaw
    .split('\n')
    .map((s) => s.trim())
    .filter((s) => s.startsWith('https://'));

  const screenshots = screenshotUrls.map((url, idx) => ({
    url,
    alt: `Capture ${idx + 1} de la configuration ${name}`,
    caption: `SHOT_${String(idx + 1).padStart(2, '0')}`,
  }));

  const sourceRepo = fields['Dépôt source des dotfiles (GitHub/GitLab/Codeberg)'] || fields['Source Repository'] || '';
  const sourceRef = fields['Commit SHA ou Tag fixe'] || fields['Git Ref'] || '';

  const scriptUrl = fields['URL du script d\'installation (.sh)'] || fields['Install Script URL'] || undefined;
  let scriptSha256 = fields['Condensat SHA-256 du script'] || fields['Script SHA-256'] || undefined;

  // Auto-calculate SHA-256 if script provided without hash
  if (scriptUrl && (!scriptSha256 || scriptSha256.length !== 64)) {
    console.log(`Downloading script ${scriptUrl} to calculate SHA-256...`);
    const res = await fetch(scriptUrl);
    if (!res.ok) throw new Error(`Could not fetch script to compute SHA-256: HTTP ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    scriptSha256 = crypto.createHash('sha256').update(buf).digest('hex');
    console.log(`Calculated SHA-256: ${scriptSha256}`);
  }

  const bar = fields['Barre d\'état'] || fields['Status Bar'] || undefined;
  const terminal = fields['Émulateur de terminal'] || fields['Terminal'] || undefined;
  const launcher = fields['Lanceur d\'applications'] || fields['Launcher'] || undefined;
  const theme = fields['Thème / Palette'] || fields['Theme'] || undefined;
  const shell = fields['Shell'] || undefined;
  const ramIdleRaw = fields['Consommation RAM au repos (MiB)'] || fields['Idle RAM'] || undefined;
  const ramIdleMiB = ramIdleRaw ? parseInt(ramIdleRaw, 10) : undefined;
  const batteryProfile = (fields['Profil batterie optimisé'] || fields['Battery Profile'] || '').toLowerCase().includes('oui') ||
    (fields['Profil batterie optimisé'] || fields['Battery Profile'] || '').toLowerCase().includes('yes');

  const config: ConfigInput = {
    $schema: '../../schema/config.schema.json',
    name,
    author: {
      name: issueAuthor,
      github: issueAuthor,
    },
    lang: 'fr',
    summary,
    description: description || undefined,
    license,
    updatedAt: new Date().toISOString().split('T')[0],
    distros: distros.length > 0 ? distros : (['arch'] as any),
    wm: wm as any,
    displayServer: displayServer as any,
    tags,
    specs: {
      bar: bar || undefined,
      terminal: terminal || undefined,
      launcher: launcher || undefined,
      theme: theme || undefined,
      shell: shell || undefined,
      ramIdleMiB: isNaN(ramIdleMiB as number) ? undefined : ramIdleMiB,
      batteryProfile: batteryProfile || undefined,
    },
    screenshots: screenshots.length > 0 ? screenshots : [{ url: 'https://raw.githubusercontent.com/placeholder.png', alt: 'Screenshot' }],
    source: {
      repo: sourceRepo,
      ref: sourceRef,
      readme: 'README.md',
    },
    install: {
      script: scriptUrl && scriptSha256 ? { url: scriptUrl, sha256: scriptSha256, shell: 'bash' } : undefined,
    },
    example: false,
  };

  return { config, author: issueAuthor, slug };
}

async function main() {
  const issueFile = process.argv[2];
  const issueAuthor = process.argv[3];

  if (!issueFile || !issueAuthor) {
    console.log('Usage: tsx scripts/issue-to-config.ts <issue-body-file> <github-author>');
    return;
  }

  const body = fs.readFileSync(issueFile, 'utf-8');
  const { config, author, slug } = await convertIssueToConfig(issueAuthor, body);

  const parsed = configSchema.safeParse(config);
  if (!parsed.success) {
    console.error('Validation error for generated config:');
    for (const issue of parsed.error.issues) {
      console.error(`- [${issue.path.join('.')}] ${issue.message}`);
    }
    process.exit(1);
  }

  const outDir = path.resolve(process.cwd(), 'configs', author);
  if (!fs.existsSync(outDir)) {
    fs.mkdirSync(outDir, { recursive: true });
  }

  const outFile = path.join(outDir, `${slug}.json`);
  fs.writeFileSync(outFile, JSON.stringify(parsed.data, null, 2), 'utf-8');
  console.log(`✓ Successfully created configuration: ${outFile}`);
}

if (process.argv[1] && process.argv[1].endsWith('issue-to-config.ts')) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
